// SPEC-03 step 1b: a track as a data asset. Id/DisplayName/Description come from content tracks.json (2D wording verbatim);
// Data is the TrackData JSON (TrackDataJson) generated by the editor TrackImporter from the 2D SVG. Tracks are rebuilt
// at runtime from this asset (decision D-25: no per-track prefabs).
#nullable enable
using System;
using DesktopDrift.Core;
using UnityEngine;

namespace DesktopDrift.Game
{
    public sealed class TrackAsset : ScriptableObject
    {
        public string Id = "";
        public string DisplayName = "";
        public string Description = "";
        public TextAsset? Data;

        public TrackData ToTrackData()
        {
            if (Data == null)
                throw new InvalidOperationException("TrackAsset '" + name + "' (id '" + Id + "') has no Data; run scripts/import-tracks.sh");
            return TrackDataJson.Deserialize(Data.text);
        }
    }
}
